from fractions import Fraction


def evaluate(expression):
    tokens = _tokenize(expression)
    if not tokens:
        raise ValueError("Empty expression")
    pos = [0]
    result = _parse_expression(tokens, pos)
    if pos[0] != len(tokens):
        raise ValueError("Unexpected token: %s" % tokens[pos[0]][1])
    return result


def _tokenize(s):
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c in ' \t\n\r\f\v':
            i += 1
        elif c.isdigit():
            j = i
            while j < n and s[j].isdigit():
                j += 1
            tokens.append(('NUM', int(s[i:j])))
            i = j
        elif c == '(':
            tokens.append(('LPAREN', c))
            i += 1
        elif c == ')':
            tokens.append(('RPAREN', c))
            i += 1
        elif c == '+':
            tokens.append(('PLUS', c))
            i += 1
        elif c == '-':
            tokens.append(('MINUS', c))
            i += 1
        elif c == '*':
            tokens.append(('STAR', c))
            i += 1
        elif c == '/':
            tokens.append(('SLASH', c))
            i += 1
        else:
            raise ValueError("Invalid character: %r" % c)
    return tokens


def _parse_expression(tokens, pos):
    result = _parse_term(tokens, pos)
    while pos[0] < len(tokens) and tokens[pos[0]][0] in ('PLUS', 'MINUS'):
        op = tokens[pos[0]][0]
        pos[0] += 1
        right = _parse_term(tokens, pos)
        result = result + right if op == 'PLUS' else result - right
    return result


def _parse_term(tokens, pos):
    result = _parse_factor(tokens, pos)
    while pos[0] < len(tokens) and tokens[pos[0]][0] in ('STAR', 'SLASH'):
        op = tokens[pos[0]][0]
        pos[0] += 1
        right = _parse_factor(tokens, pos)
        if op == 'STAR':
            result = result * right
        else:
            if right == 0:
                raise ZeroDivisionError("division by zero")
            result = result / right
    return result


def _parse_factor(tokens, pos):
    sign = 1
    while pos[0] < len(tokens) and tokens[pos[0]][0] in ('PLUS', 'MINUS'):
        if tokens[pos[0]][0] == 'MINUS':
            sign = -sign
        pos[0] += 1
    result = _parse_primary(tokens, pos)
    return result if sign == 1 else -result


def _parse_primary(tokens, pos):
    if pos[0] >= len(tokens):
        raise ValueError("Unexpected end of expression")
    tok_type, tok_val = tokens[pos[0]]
    if tok_type == 'NUM':
        pos[0] += 1
        return Fraction(tok_val)
    if tok_type == 'LPAREN':
        pos[0] += 1
        result = _parse_expression(tokens, pos)
        if pos[0] >= len(tokens) or tokens[pos[0]][0] != 'RPAREN':
            raise ValueError("Expected ')'")
        pos[0] += 1
        return result
    raise ValueError("Expected number or '(', got %r" % tok_val)
